// MIT — Native dataset entry point for the application process boundary.
// Every acquisition, page, lock, recovery and export belongs to the original runtime.
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import {executeLostOutputCommand} from './dataset-recovery.mjs';
import { absolute, readJson, writeJson, writeBytes, jsonBytes, exists, object, need, safeCode } from './store.mjs';

const [runtimePath, entryPath, command, requestPath, resultPath] = process.argv.slice(2);
const runtime = absolute(runtimePath), entry = absolute(entryPath);
const load = name => import(pathToFileURL(join(runtime, name)).href);
const controller = new AbortController();
const stop = () => controller.abort();
process.once('SIGINT', stop); process.once('SIGTERM', stop);

async function main() {
  const metadata = await readJson(join(entry, 'dataset.json'));
  need(metadata.schema === 'stellar-forge.node-dataset.v1' && metadata.entryDirectory === entry,
    'DATASET_APPLICATION_STATE_INVALID');
  const directory = absolute(metadata.sessionDirectory);
  const api = await load('dataset-session.mjs');
  const { canonical, digest } = await load('dataset-page.mjs');
  const request = await readJson(absolute(requestPath));
  need(Number.isSafeInteger(request.reportLimit) && request.reportLimit >= 1048576 &&
    request.reportLimit <= 268435456, 'DATASET_REPORT_LIMIT_INVALID');
  const bindingPath = join(entry, 'binding.json');
  let binding = await exists(bindingPath) ? await readJson(bindingPath) : null;
  const check = report => {
    need(object(report) && report.schema === 'stellar-forge.sf88.dataset-acquisition.v1' &&
      report.directory === directory, 'DATASET_NATIVE_REPORT_INVALID');
    if (report.status !== 'RUNNING') {
      need(binding && report.configurationSha256 === binding.configurationSha256 &&
        report.sessionId === binding.sessionId && report.expectedSnapshot === binding.expectedSnapshot &&
        canonical(report.limits) === canonical(binding.limits) &&
        (report.workspaceDirectory ?? null) === binding.workspaceDirectory,
      'DATASET_APPLICATION_BINDING_CHANGED');
    }
    return report;
  };
  const bind = async value => {
    const proposed = { schema:'stellar-forge.node-dataset-binding.v1', id:metadata.id,
      sessionDirectory:directory, configurationSha256:value.configurationSha256,
      sessionId:value.sessionId, limits:value.limits, expectedSnapshot:value.expectedSnapshot,
      workspaceDirectory:value.workspaceDirectory ?? null };
    if (binding) need(canonical(binding) === canonical(proposed), 'DATASET_APPLICATION_BINDING_CHANGED');
    else {
      try { await writeJson(bindingPath, proposed, {exclusive:true}); }
      catch (error) { if (error.code !== 'EEXIST') throw error; }
      binding = await readJson(bindingPath);
      need(canonical(binding) === canonical(proposed), 'DATASET_APPLICATION_BINDING_CHANGED');
    }
  };
  if (binding) need(binding.schema === 'stellar-forge.node-dataset-binding.v1' &&
    binding.id === metadata.id && binding.sessionDirectory === directory,
  'DATASET_APPLICATION_BINDING_CHANGED');

  let result;
  if (command === 'initialize') {
    need(metadata.source?.kind === 'config' || metadata.source?.kind === 'workspace',
      'DATASET_INITIALIZATION_SOURCE_REQUIRED');
    const source = metadata.source.kind === 'config'
      ? await (await load('config.mjs')).config(join(entry, 'config.json'))
      : (await (await load('workspace.mjs')).openWorkspace(['--dir', metadata.source.directory])).config;
    const selected = new URL(source.operation.url).searchParams.get('snapshot');
    await bind({configurationSha256:digest(canonical(source)), sessionId:source.operation.intentId,
      limits:metadata.limits, expectedSnapshot:metadata.expectedSnapshot ?? selected ?? null,
      ...(metadata.source.kind === 'workspace' ? {workspaceDirectory:metadata.source.directory} : {})});
    if (await exists(join(directory, 'session.json'))) result = check(await api.inspectDatasetSession(directory));
    else result = check(await api.createDatasetSession({directory,
      ...(metadata.source.kind === 'workspace' ? {workspaceDirectory:metadata.source.directory}
        : {configPath:join(entry, 'config.json')}), ...metadata.limits,
      expectedSnapshot:metadata.expectedSnapshot}));
  } else if (command === 'attach') {
    need(metadata.source?.kind === 'attached', 'DATASET_ATTACHMENT_SOURCE_REQUIRED');
    result = await api.inspectDatasetSession(directory);
    need(result.status !== 'RUNNING', 'DATASET_SESSION_RUNNING_USE_STATUS');
    await bind(result); check(result);
  } else if(command==='attach-recovery') {
    need(metadata.source?.kind==='attached','DATASET_RECOVERY_ATTACHMENT_REQUIRED');
    const definition=api.validateDatasetDefinition(await readJson(join(directory,'session.json'),262144),directory);
    await bind({configurationSha256:definition.configurationSha256,sessionId:definition.config.operation.intentId,
      limits:definition.limits,expectedSnapshot:definition.expectedSnapshot,
      workspaceDirectory:definition.workspaceDirectory??null});
    result={schema:'stellar-forge.node-dataset-recovery-attachment.v1',directory,
      sessionId:binding.sessionId,configurationSha256:binding.configurationSha256,
      limits:binding.limits,expectedSnapshot:binding.expectedSnapshot,workspaceDirectory:binding.workspaceDirectory};
  } else if(['inspect-lost-output','recover-lost-output','read-lost-output','export-lost-output'].includes(command)) {
    await executeLostOutputCommand({runtime,entry,metadata,binding,request,requestPath:absolute(requestPath),
      resultPath:absolute(resultPath),command,signal:controller.signal});
    return;
  } else if (command === 'accounting' || command === 'finalize') {
    need(binding || command === 'accounting' && request.initializeAccounting === true &&
      metadata.source.kind === 'attached', 'DATASET_INITIALIZE_OR_ATTACH_REQUIRED');
    const definition = await readJson(join(directory, 'session.json'), 262144);
    const selectedBinding = binding ?? {
      sessionId:definition.config?.operation?.intentId, configurationSha256:definition.configurationSha256,
      expectedSnapshot:definition.expectedSnapshot, limits:definition.limits,
      workspaceDirectory:definition.workspaceDirectory ?? null};
    need(definition.schema === 'stellar-forge.sf88.dataset-session.v1' && definition.directory === directory &&
      definition.config?.operation?.intentId === selectedBinding.sessionId &&
      digest(canonical(definition.config)) === selectedBinding.configurationSha256 &&
      definition.configurationSha256 === selectedBinding.configurationSha256 &&
      definition.expectedSnapshot === selectedBinding.expectedSnapshot &&
      canonical(definition.limits) === canonical(selectedBinding.limits) &&
      (definition.workspaceDirectory ?? null) === selectedBinding.workspaceDirectory,
    'DATASET_APPLICATION_BINDING_CHANGED');
    // Accounting does not inspect or require product pages. The original native
    // entrypoint verifies the saved definition, attempts and financial evidence.
    result = await api.accountDatasetSession(directory, {workspace:request.workspaceDirectory ?? undefined,
      offset:request.offset, limit:request.limit, finalize:command === 'finalize', signal:controller.signal,
      outbox:request.outboxDirectory ?? undefined, merchantRoute:request.merchantRoute ?? undefined});
    need(result.schema === 'stellar-forge.sf88.session-accounting.v1' && result.kind === 'dataset' &&
      result.directory === directory && result.sessionId === selectedBinding.sessionId &&
      result.configurationSha256 === selectedBinding.configurationSha256, 'DATASET_ACCOUNTING_BINDING_CHANGED');
    if (request.initializeAccounting === true) await bind(selectedBinding);
    if (result.interrupted) process.exitCode = 130;
    else if (command === 'finalize' && result.entries.some(entry =>
      !['FINALIZED','IDEMPOTENT_FINALIZED','NO_PAYMENT_REQUIRED','NOT_ATTEMPTED'].includes(entry.outcome))) process.exitCode = 2;
  } else {
    need(binding, 'DATASET_INITIALIZE_OR_ATTACH_REQUIRED');
    // Offline inspection checks the immutable original definition before a new run.
    const current = command === 'recover'
      ? await api.recoverDatasetSession(directory) : await api.inspectDatasetSession(directory);
    check(current);
    if (command === 'inspect' || command === 'recover') result = current;
    else if (command === 'run') {
      need(current.status !== 'RUNNING', 'DATASET_SESSION_RUNNING_USE_STATUS');
      result = check(await api.runDatasetSession(directory, {signal:controller.signal,
        environment:process.env, emitPageSummaries:false}));
    } else if (command === 'deliver') {
      need(current.status === 'COMPLETE', 'DATASET_COMPLETE_SESSION_REQUIRED');
      result = await api.deliverDatasetSession(directory, absolute(request.destination));
      need(result.schema === 'stellar-forge.sf88.dataset-delivery.v1' && result.sourceDirectory === directory,
        'DATASET_NATIVE_DELIVERY_INVALID');
    } else if (command === 'manifest') {
      need(current.status === 'COMPLETE', 'DATASET_COMPLETE_SESSION_REQUIRED');
      result = await api.exportDatasetManifest(directory, absolute(request.destination));
    } else need(false, 'DATASET_APPLICATION_COMMAND_INVALID');
  }
  const bytes = jsonBytes({schema:'stellar-forge.node-dataset-command.v1', id:metadata.id, command, result});
  need(bytes.length <= request.reportLimit, 'DATASET_REPORT_LIMIT_EXCEEDED');
  await writeBytes(absolute(resultPath), bytes, {exclusive:true});
}

main().catch(error => {
  process.stderr.write(JSON.stringify({error:safeCode(error?.code, 'DATASET_APPLICATION_COMMAND_FAILED')}) + '\n');
  process.exitCode = 1;
}).finally(() => {
  process.removeListener('SIGINT', stop); process.removeListener('SIGTERM', stop);
});

// MIT — Node application access to the original SF88 acquisition and SF100 outputs.
import { mkdtemp, readdir, rm, rename } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { VerifiedFile } from './result.mjs';
import {runLostOutput,recoverLostOutputCommand,resumeLostOutputCommand,listLostOutputCommands,
 recoveryProofFile,exportLostOutputReport} from './dataset-recovery.mjs';
import { accountingOptions, runAccounting, recoverAccounting, accountingPages,
  exportAccounting } from './session-accounting.mjs';
import { absolute, privateDirectory, digest, now, intent, object, need, BuyerError,
  readJson, writeJson, exists, jsonBytes, syncDirectory } from './store.mjs';

const SCHEMA = 'stellar-forge.node-dataset.v1';
const WORKER = fileURLToPath(new URL('./dataset-worker.mjs', import.meta.url));
const OUTPUTS = new Set(['dataset.jsonl','dataset.csv','review.html','manifest.json','semantics.json']);
const MAX_OUTPUT = 256 * 1024 * 1024;
const clone = value => JSON.parse(jsonBytes(value));
const freeze = value => {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
};

export class Dataset {
  constructor(buyer, id) {
    this.buyer = buyer;
    this.id = intent(id);
    this.directory = join(buyer.stateDirectory, 'datasets', digest(this.id));
  }
  async _metadata() {
    await privateDirectory(this.directory, {create:false});
    const metadata = await readJson(join(this.directory, 'dataset.json'));
    need(metadata.schema === SCHEMA && metadata.id === this.id &&
      metadata.entryDirectory === this.directory && object(metadata.source), 'DATASET_APPLICATION_STATE_INVALID');
    absolute(metadata.sessionDirectory);
    return metadata;
  }
  async _command(command, request = {}, {signal} = {}) {
    await this._metadata();
    const jobs = await privateDirectory(join(this.directory, 'commands'));
    const directory = await mkdtemp(join(jobs, command + '-'));
    const requestPath = join(directory, 'request.json'), resultFile = join(directory, 'result.json');
    await writeJson(requestPath, {...request, reportLimit:this.buyer.datasetReportLimit}, {exclusive:true});
    const run = await this.buyer.runtime.run(
      [this.buyer.runtime.directory, this.directory, command, requestPath, resultFile],
      {directory, signal, entryFile:WORKER, resultFile, resultLimit:this.buyer.datasetReportLimit});
    const output = run.output;
    if (!output || output.schema !== 'stellar-forge.node-dataset-command.v1' ||
      output.id !== this.id || output.command !== command || !object(output.result)) {
      throw new BuyerError(run.errorCode ?? 'DATASET_NATIVE_RESULT_UNAVAILABLE',
        {dataset:this, exitCode:run.exitCode, commandDirectory:directory});
    }
    const process = {exitCode:run.exitCode, exitSignal:run.exitSignal, errorCode:run.errorCode};
    // The original native session is the recovery authority. Keep only the latest
    // complete command receipt; a failed/uncertain command retains its private logs.
    await writeJson(join(this.directory, 'last-command.json'), {command, completedAt:now(), process,
      result:output.result});
    if (run.exitCode === 0 && !run.errorCode) await rm(directory, {recursive:true, force:true});
    return {native:freeze(output.result), process:freeze(process)};
  }
  /** Offline initialization can be repeated after a lost creation response. */
  async initialize(options) {
    const metadata = await this._metadata();
    return this._command(metadata.source.kind === 'attached' ? 'attach' : 'initialize', {}, options);
  }
  /** Bind an attached original definition while its returned paid page is being recovered. */
  async initializeRecovery(options) {
    need((await this._metadata()).source.kind==='attached','DATASET_RECOVERY_ATTACHMENT_REQUIRED');
    return this._command('attach-recovery',{},options);
  }
  inspect(options) { return this._command('inspect', {}, options); }
  inspectLostOutput(options) { return runLostOutput(this,'inspect-lost-output',options); }
  recoverLostOutput(options) { return runLostOutput(this,'recover-lost-output',options); }
  /** Authenticates the original sealed completion and ledger without provider IO. */
  readLostOutputRecovery(options) { return runLostOutput(this,'read-lost-output',options); }
  async exportLostOutputProof(destination,options={}) {
    const result=await runLostOutput(this,'export-lost-output',
      {...options,...(destination===undefined?{}:{destination:absolute(destination)})});
    return {...result,file:recoveryProofFile(result)};
  }
  lostOutputProofFile(result) {
    need(/^lost-output-[a-f0-9]{64}$/.test(result?.commandId??'')&&
      result.commandDirectory===join(this.directory,'commands',result.commandId),
    'DATASET_RECOVERY_APPLICATION_BINDING_CHANGED');
    return recoveryProofFile(result);
  }
  recoverLostOutputCommand(options) { return recoverLostOutputCommand(this,options); }
  resumeLostOutputCommand(options) { return resumeLostOutputCommand(this,options); }
  listLostOutputCommands(options) { return listLostOutputCommands(this,options); }
  exportLostOutputReport(destination,options) { return exportLostOutputReport(this,destination,options); }
  /** Original recovery only reads native files and removes a proven-dead native lock. */
  recover(options) { return this._command('recover', {}, options); }
  /** Only this method can acquire new pages. Completed/marked pages are never replayed. */
  run(options) { return this._command('run', {}, options); }
  async _accountingIdentity({allowUnbound = false} = {}) {
    const metadata = await this._metadata();
    const definition = await readJson(join(metadata.sessionDirectory, 'session.json'), 262144);
    const bindingPath = join(this.directory, 'binding.json');
    const bound = await exists(bindingPath);
    need(bound || allowUnbound && metadata.source.kind === 'attached', 'DATASET_INITIALIZE_OR_ATTACH_REQUIRED');
    const binding = bound ? await readJson(bindingPath) : {
      schema:'stellar-forge.node-dataset-binding.v1', id:this.id,
      sessionDirectory:metadata.sessionDirectory, sessionId:definition.config?.operation?.intentId,
      configurationSha256:definition.configurationSha256, limits:definition.limits,
      expectedSnapshot:definition.expectedSnapshot, workspaceDirectory:definition.workspaceDirectory ?? null};
    const {canonical, digest:sourceDigest} = await import(pathToFileURL(
      join(this.buyer.runtime.directory, 'dataset-page.mjs')).href);
    // Bind the original definition without opening a page response or delivery.
    // The native accounting entrypoint still validates each original attempt.
    need(binding.schema === 'stellar-forge.node-dataset-binding.v1' && binding.id === this.id &&
      binding.sessionDirectory === metadata.sessionDirectory &&
      definition.schema === 'stellar-forge.sf88.dataset-session.v1' &&
      definition.directory === binding.sessionDirectory &&
      definition.config?.operation?.intentId === binding.sessionId &&
      sourceDigest(canonical(definition.config)) === binding.configurationSha256 &&
      definition.configurationSha256 === binding.configurationSha256 &&
      definition.expectedSnapshot === binding.expectedSnapshot &&
      canonical(definition.limits) === canonical(binding.limits) &&
      (definition.workspaceDirectory ?? null) === binding.workspaceDirectory,
    'DATASET_APPLICATION_BINDING_CHANGED');
    return {kind:'dataset', id:this.id, entryDirectory:this.directory,
      sessionDirectory:metadata.sessionDirectory, sessionId:binding.sessionId,
      configurationSha256:binding.configurationSha256, workspace:binding.workspaceDirectory};
  }
  async _accounting(action, input, {initialize = false} = {}) {
    const options = accountingOptions(input, action === 'finalize');
    const identity = await this._accountingIdentity({allowUnbound:initialize});
    return runAccounting(this, identity, action, options, {outputFile:'native.json',
      invoke:async ({directory, signal, resultFile}) => {
        const {signal:unused, ...request} = options;
        const requestPath = join(directory, 'request.json');
        await writeJson(requestPath, {...request, reportLimit:this.buyer.datasetReportLimit,
          initializeAccounting:initialize}, {exclusive:true});
        return this.buyer.runtime.run([this.buyer.runtime.directory, this.directory, action, requestPath, resultFile],
          {directory, signal, entryFile:WORKER, resultFile, resultLimit:this.buyer.datasetReportLimit});
      }});
  }
  /** Original page views, available independently of delivered dataset bytes. */
  accounting(options) { return this._accounting('accounting', options); }
  /** Attach an original financial account even after delivered pages were removed. */
  async initializeAccounting(options) {
    need((await this._metadata()).source.kind === 'attached', 'DATASET_ACCOUNTING_ATTACHMENT_REQUIRED');
    return this._accounting('accounting', options, {initialize:true});
  }
  /** Continue existing reservations through the original SF36/SF86 finalizer. */
  finalize(options) { return this._accounting('finalize', options); }
  accountingPages(options) { return accountingPages(this, options); }
  finalizeAll(options) { return accountingPages(this, options, true); }
  async recoverAccounting(options) {
    return recoverAccounting(this, await this._accountingIdentity(), options);
  }
  exportAccounting(destination, options) { return exportAccounting(this, destination, options); }
  async exportManifest(destination, options) {
    return this._command('manifest', {destination:absolute(destination)}, options);
  }
  /** Builds or reopens the original SF100 data room, entirely offline. */
  async deliver(destination = join(this.directory, 'delivery'), options) {
    const result = await this._command('deliver', {destination:absolute(destination)}, options);
    need(result.process.exitCode === 0 && !result.process.errorCode,
      result.process.errorCode ?? 'DATASET_DELIVERY_NOT_COMPLETE');
    return DatasetDelivery.open(result.native);
  }
}

export async function createDataset(buyer, options, attached = false) {
  need(object(options), 'DATASET_OPTIONS_REQUIRED');
  const {id, config, workspaceDirectory, directory, operatorProfile,
    maxPages, maxTotalAtomic, maxRows = 1000000, maxPageBytes = 1048576, expectedSnapshot = null,
    accountingOnly = false, recoveryOnly = false} = options;
  need(typeof accountingOnly === 'boolean' && (attached || !accountingOnly), 'DATASET_ACCOUNTING_ATTACHMENT_REQUIRED');
  need(typeof recoveryOnly==='boolean'&&(attached||!recoveryOnly)&&!(recoveryOnly&&accountingOnly),
    'DATASET_RECOVERY_ATTACHMENT_REQUIRED');
  const dataset = new Dataset(buyer, id);
  await buyer.ready();
  await privateDirectory(join(buyer.stateDirectory, 'datasets'));
  const metadata = {schema:SCHEMA, id:dataset.id, entryDirectory:dataset.directory,
    sessionDirectory:attached ? absolute(directory) : join(dataset.directory, 'session'),
    createdAt:now(), source:attached ? {kind:'attached'} : workspaceDirectory !== undefined
      ? {kind:'workspace', directory:absolute(workspaceDirectory)} : {kind:'config'}};
  let input;
  if (!attached) {
    need((config !== undefined) !== (workspaceDirectory !== undefined), 'DATASET_ONE_CONFIG_SOURCE_REQUIRED');
    if (workspaceDirectory !== undefined) need(operatorProfile === undefined, 'DATASET_WORKSPACE_PROFILE_UNSUPPORTED');
    metadata.limits = {maxPages,maxTotalAtomic,maxRows,maxPageBytes};
    metadata.expectedSnapshot = expectedSnapshot;
    // Reject non-JSON values before allocating a named application entry.
    jsonBytes(metadata);
    if (config !== undefined) input = await buyer._profile(typeof config === 'string'
      ? await readJson(absolute(config)) : clone(config), operatorProfile);
  }
  if (await exists(dataset.directory)) throw new BuyerError('DATASET_ALREADY_EXISTS_USE_OPEN', {dataset});
  const parent = join(buyer.stateDirectory, 'datasets');
  // Publish a complete entry once. A crash while writing the private stage cannot
  // reserve the stable name or make listDatasets encounter half-written metadata.
  const stage = await mkdtemp(join(parent, '.dataset-stage-'));
  if (input) await writeJson(join(stage, 'config.json'), input, {exclusive:true});
  await writeJson(join(stage, 'dataset.json'), metadata, {exclusive:true});
  await syncDirectory(stage);
  try { await rename(stage, dataset.directory); }
  catch (error) {
    // A concurrently published entry is nonempty and cannot be replaced by rename.
    if (['EEXIST','ENOTEMPTY'].includes(error.code))
      throw new BuyerError('DATASET_ALREADY_EXISTS_USE_OPEN', {dataset, stagingDirectory:stage});
    throw error;
  }
  await syncDirectory(parent);
  if (recoveryOnly) await dataset.initializeRecovery();
  else if (accountingOnly) await dataset.initializeAccounting();
  else await dataset.initialize();
  return dataset;
}

export async function* listDatasets(buyer) {
  await buyer.ready();
  const directory = join(buyer.stateDirectory, 'datasets');
  if (!await exists(directory)) return;
  await privateDirectory(directory, {create:false});
  for (const entry of await readdir(directory, {withFileTypes:true})) {
    if (!entry.isDirectory() || !/^[a-f0-9]{64}$/.test(entry.name)) continue;
    const metadata = await readJson(join(directory, entry.name, 'dataset.json'));
    need(metadata.schema === SCHEMA && digest(intent(metadata.id)) === entry.name,
      'DATASET_APPLICATION_STATE_INVALID');
    yield new Dataset(buyer, metadata.id);
  }
}

/** A file from an original, verified SF100 export. No native purchase summary is fabricated. */
export class DatasetFile extends VerifiedFile {
  constructor(metadata, directory) {
    super();
    this.metadata = freeze(clone(metadata));
    this.directory = absolute(directory);
  }
  _metadata() {
    const saved = this.metadata;
    need(object(saved) && OUTPUTS.has(saved.name) && saved.path === join(this.directory, saved.name) &&
      Number.isSafeInteger(saved.bytes) && saved.bytes >= 0 && saved.bytes <= MAX_OUTPUT &&
      typeof saved.sha256 === 'string' && /^[a-f0-9]{64}$/.test(saved.sha256),
    'DATASET_OUTPUT_METADATA_INVALID');
    return saved;
  }
}

export class DatasetDelivery {
  constructor(report, manifest) {
    this.report = freeze(clone(report));
    this.manifest = freeze(clone(manifest));
  }
  static async open(report) {
    need(report?.schema === 'stellar-forge.sf88.dataset-delivery.v1' &&
      report.nativeStatus?.finalized === true && object(report.outputs), 'DATASET_NATIVE_DELIVERY_INVALID');
    const file = new DatasetFile({name:'manifest.json', ...report.outputs['manifest.json']}, report.directory);
    const manifest = await file.json({limit:4 * 1024 * 1024});
    need(manifest?.schema === 'stellar-forge.buyer-delivery-manifest.v1' &&
      manifest.dataset?.snapshot === report.nativeStatus.snapshot &&
      manifest.dataset.rows === report.nativeStatus.rows && Array.isArray(manifest.dataset.projectedFields) &&
      object(manifest.outputs), 'DATASET_NATIVE_MANIFEST_INVALID');
    const semantics = manifest.semantics;
    need((semantics !== undefined) === (report.semantics !== undefined),
      'DATASET_SEMANTIC_OUTPUT_METADATA_INVALID');
    if (semantics !== undefined) need(object(semantics) && semantics.file === 'semantics.json' &&
      semantics.scope === 'PUBLISHED_DATASET' && semantics.typedRowsFile === 'dataset.jsonl' &&
      ['schema','sha256','definitionSha256','captureManifestSha256'].every(key =>
        semantics[key] === report.semantics[key] && semantics[key] === report.nativeStatus.semantics?.[key]) &&
      JSON.stringify(semantics.selectedFields) === JSON.stringify(manifest.dataset.projectedFields),
      'DATASET_SEMANTIC_OUTPUT_METADATA_INVALID');
    for (const name of ['dataset.jsonl','dataset.csv','review.html',
      ...(semantics !== undefined ? ['semantics.json'] : [])])
      need(manifest.outputs[name]?.sha256 === report.outputs[name]?.sha256 &&
        manifest.outputs[name]?.bytes === report.outputs[name]?.bytes, 'DATASET_OUTPUT_METADATA_INVALID');
    return new DatasetDelivery(report, manifest);
  }
  file(name) {
    need(OUTPUTS.has(name), 'DATASET_OUTPUT_NAME_INVALID');
    return new DatasetFile({name, ...this.report.outputs[name]}, this.report.directory);
  }
  /** The retained published dictionary; selectedFields remain in the delivery manifest. */
  async readSemantics({limit = 2097152, signal} = {}) {
    if (this.manifest.semantics === undefined) return null;
    const value = await this.file('semantics.json').json({limit, signal});
    const binding = this.manifest.semantics;
    need(value?.schema === binding.schema && value.sha256 === binding.sha256 &&
      value.definitionSha256 === binding.definitionSha256 &&
      value.source?.captureManifestSha256 === binding.captureManifestSha256,
      'DATASET_SEMANTIC_DICTIONARY_CHANGED');
    return value;
  }
  _row(text) {
    let value;
    try { value = JSON.parse(text); } catch { throw new BuyerError('DATASET_ROW_JSON_INVALID'); }
    const fields = this.manifest.dataset.projectedFields;
    need(object(value) && Object.keys(value).length === fields.length && fields.every(field =>
      Object.hasOwn(value, field) && (value[field] === null || ['string','number','boolean'].includes(typeof value[field]))),
    'DATASET_ROW_SHAPE_INVALID');
    return value;
  }
