    const text = new TextDecoder('utf-8', {fatal:true}).decode(bytes);
    const lines = text.length ? text.replace(/\n$/, '').split('\n') : [];
    need(lines.length === this.manifest.dataset.rows, 'DATASET_ROW_COUNT_CHANGED');
