  need(sdk.schema === 'commons.stellar-authorization-expiry-sdk-source/v1' && sdk.package === '@x402/stellar' && sdk.version === '2.28.0', 'Unsupported authorization expiry SDK source');
  equal(sdk.formula, FORMULA, 'SDK expiry formula');
