    previousTime = time;
    integer(tx.ledger, 'Original transaction ledger', 1);
    need(tx.ledger <= horizon.history_latest_ledger, 'Account transaction lies beyond the observed history ledger');
    if (time >= attemptTime) afterAttempt.push({ hash: tx.hash, ledger: tx.ledger, createdAt: tx.created_at, successful: tx.successful });
    if (tx.source_account === expectedFeeAccount) {
      need(/^\d+$/.test(tx.source_account_sequence), 'Original fee-account transaction sequence is invalid');
      const sequence = BigInt(tx.source_account_sequence);
      if (largestSourceSequence === null || sequence > largestSourceSequence) largestSourceSequence = sequence;
    }
  }
  need(afterAttempt.length === 0, 'Original fee-account history contains activity at or after this attempt', 'AUTHORIZATION_EXPIRY_EVIDENCE_HAS_LATER_ACTIVITY');
  equal(observation.history.transactions_after_original_attempt_start, [], 'Recorded transactions after the original attempt');
  need(largestSourceSequence !== null && largestSourceSequence === BigInt(account.sequence), 'Original account sequence does not match its complete returned history');
  need(observation.history.newest_created_at === transactions[0].created_at && observation.history.oldest_created_at === transactions.at(-1).created_at, 'Account history time range differs from its records');
  const prior = index.account_history?.known_prior_payments_found;
  need(Array.isArray(prior) && prior.length === association.completed_native_pages && prior.length > 0, 'Serial provider association must retain the original completed native pages');
  need(new Set(prior).size === prior.length, 'Original completed native page identities repeat');
  for (const payment of prior) {
    hash(payment, 'Original prior payment');
    const tx = transactions.find(row => row.hash === payment);
    need(tx && tx.successful === true && tx.source_account === expectedFeeAccount && tx.fee_account === expectedFeeAccount, 'An original completed native page is missing from the configured fee-account history');
  }
  need(observation.history.known_page1_present === true && observation.history.known_page2_present === true, 'Original completed page presence is inconsistent');

  const files = await io.finish();
  const cleanWindows = windows.map(({ headerDate, ended, ...value }) => value);
  const observedAt = windows.reduce((a, b) => a.ended > b.ended ? a : b).retrievedAt;
  const snapshot = {
    schema: SCHEMA,
    kind: 'SOURCE_BOUND_LEDGER_UPPER_BOUND',
    binding: {
      intentId: expectedIntentId, requestSha256: expectedRequestSha256,
      feeAccount: expectedFeeAccount, acceptedMaxTimeoutSeconds,
      attemptStartedAt: expectedAttemptStartedAt
    },
    bound: {
      providerCompletedAt: completedAt,
      signingLedgerUpperBound: after.sequence,
      maximumAdditionalLedgers: extraLedgers,
      authorizationExpiryLedgerUpperBound: upper,
      lastClosedBeforeCompletion: point(before),
      firstClosedAfterCompletion: point(after)
    },
    observation: {
      networkPassphrase: horizon.network_passphrase,
      historyLedger: horizon.history_latest_ledger, coreLedger: horizon.core_latest_ledger,
      ingestLedger: horizon.ingest_latest_ledger, historyLedgerClosedAt: horizon.history_latest_ledger_closed_at,
      feeAccountSequence: account.sequence, lastModifiedLedger: account.last_modified_ledger,
      lastModifiedAt: account.last_modified_time, historyCount: transactions.length,
      historyLimit, completeReturnedPage: true, transactionsAfterAttemptStart: afterAttempt,
      knownPriorPayments: [...prior], observedAt, sourceWindows: cleanWindows
    },
    sdk: { package: '@x402/stellar', version: '2.28.0', formula: FORMULA, sourceHashes: sdkHashes },
    provider: {
      account: association.account, selectedPage: association.selected_page,
      completedNativePages: association.completed_native_pages,
      originalCallsForUtcDay: dayBudget.calls, originalSettledCreditsForUtcDay: dayBudget.settledCredits,
      remainingAtResponse: accountBudget.remaining, completedAtPointer: '/lastResponseAt'
    },
    scope: {
      exactSignedAuthorizationRetained: false,
      clockBasis: inference.clock_basis,
      historyScope: 'original_fee_account',
      providerAssociation: 'ORIGINAL_SERIAL_NATIVE_COHORT',
      providerAssociationScope: association.scope,
      observationConsistency: 'Separate retained Horizon responses with their original request and response windows',
      inferenceCondition: 'The original SDK signed before the associated serial provider response; its retained formula gives an inclusive ledger upper bound'
    },
    files
  };
  const fixed = JSON.parse(canonical(snapshot));
  return { ...fixed, sha256: sha(Buffer.from(canonical(fixed), 'utf8')) };
}

#!/usr/bin/env node
// MIT — One selected command in the installed original SF88 inbox.
import { mkdtemp, lstat, realpath, rename, rm } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { absolute, digest, intent, object, need, safeCode, readBytes, readJson,
  writeJson, syncDirectory } from './store.mjs';

const SCHEMA = 'stellar-forge.node-buyer-inbox-command.v1';
const INBOX = 'stellar-forge.sf88.buyer-inbox.v1';
const controller = new AbortController();
let signalExit;
const interrupt = () => { signalExit = 130; controller.abort(); };
const terminate = () => { signalExit = 143; controller.abort(); };
process.once('SIGINT', interrupt);
process.once('SIGTERM', terminate);

async function main([runtimeDirectory, inputFile, resultFile, ...extra]) {
  need(extra.length === 0, 'INBOX_WORKER_ARGUMENTS_INVALID');
  runtimeDirectory = absolute(runtimeDirectory);
  const input = await readJson(absolute(inputFile));
  need(input.schema === SCHEMA && typeof input.command === 'string', 'INBOX_WORKER_INPUT_INVALID');
  const original = name => import(pathToFileURL(join(runtimeDirectory, name)).href);
  let queue, native = null, responseFile = null, error = null;
  try {
    need(!controller.signal.aborted, 'OPERATION_ABORTED_BEFORE_START');
    if (input.command === 'inspect-packet') {
      const { inspectOperationHandoff } = await original('operation-handoff.mjs');
      native = await inspectOperationHandoff({ file:absolute(input.file),
        directory:dirname(absolute(inputFile)), acceptIndex:input.accept });
    } else {
      const root = absolute(input.root);
      const { initializeQueue, openQueue, saveQueueReport } = await original('queue.mjs');
      if (input.command === 'create') {
        // The native queue's metadata has no absolute root binding. Publish its
        // complete, empty original structure rather than a partly initialized name.
        const parent = dirname(root);
        need(await realpath(parent) === parent, 'INBOX_CANONICAL_PARENT_REQUIRED');
        const parentInfo = await lstat(parent);
        need(parentInfo.isDirectory() && (process.platform === 'win32' ||
          (parentInfo.mode & 0o077) === 0 && (!process.getuid || parentInfo.uid === process.getuid())),
        'INBOX_PRIVATE_PARENT_REQUIRED');
        let present = false;
        try { await lstat(root); present = true; } catch (problem) { if (problem.code !== 'ENOENT') throw problem; }
        need(!present, 'INBOX_ALREADY_EXISTS_USE_EXISTING');
        const temporary = await mkdtemp(join(parent, '.inbox-create-'));
        try {
          const staged = join(temporary, 'ready');
          await initializeQueue(staged);
          // A complete native inbox is nonempty, so rename cannot replace one.
          await rename(staged, root);
          await syncDirectory(parent);
        } finally { await rm(temporary, { recursive:true, force:true }); }
        queue = await openQueue(root);
        native = { schema:INBOX, root:queue.root };
      } else {
        queue = await openQueue(root);
        if (input.command === 'open') native = { schema:INBOX, root:queue.root };
        else if (input.command === 'list') native = { schema:INBOX, root:queue.root, jobs:await queue.list() };
        else if (input.command === 'enqueue') {
          const file = absolute(input.configFile);
          if (input.expectedConfigSha256 !== undefined)
            need(digest(await readBytes(file)) === input.expectedConfigSha256, 'OPERATION_INPUT_CHANGED');
          native = await queue.enqueue(file);
          if (input.expectedConfigSha256 !== undefined)
            need(native.sourceConfigSha256 === input.expectedConfigSha256, 'INBOX_SOURCE_CONFIG_CHANGED');
          if (input.expectedBodySha256 !== undefined)
            need((native.bodySha256 ?? digest(Buffer.alloc(0))) === input.expectedBodySha256, 'INBOX_SOURCE_BODY_CHANGED');
          if (input.expectedTicketSha256 !== undefined)
            need((native.operationTicket?.sha256 ?? null) === input.expectedTicketSha256, 'INBOX_SOURCE_TICKET_CHANGED');
        } else if (input.command === 'report') {
          const { renderQueueReport } = await original('queue-report.mjs');
          const { readLostOutputQueueViews } = await original('lost-output.mjs');
          native = await saveQueueReport(absolute(input.destination), renderQueueReport({
            jobs:await readLostOutputQueueViews({root:queue.root,workspace:input.workspaceDirectory,
              signal:controller.signal}), queueRoot:queue.root,
            accountingWorkspace:input.workspaceDirectory,
          }));
        } else {
          const intentId = intent(input.intentId);
          if (['inspect-lost-output','recover-lost-output','read-lost-output','export-lost-output'].includes(input.command)) {
            const originalRecovery = await original('lost-output.mjs');
            const options = {root, intentId, workspace:absolute(input.workspaceDirectory),
              signal:controller.signal, environment:process.env};
            for (const name of ['approvedRequestFile','approvedRequest','expectedRequestSha256',
              'expectedAttemptId','expectedConfigSha256','transaction'])
              if (input[name] !== undefined) options[name] = input[name];
            if (input.command === 'inspect-lost-output') {
              const snapshot = await originalRecovery.inspectLostOutputAttempt(options);
              native = {...await queue.show(intentId), lostOutputAttempt:snapshot};
            } else if (input.command === 'recover-lost-output')
              native = await originalRecovery.recoverLostOutput(options);
            else if (input.command === 'read-lost-output') {
              const recovered = await originalRecovery.readLostOutputRecovery(options);
              native = {...await queue.show(intentId), lostOutputFinalization:recovered};
            } else {
              const exported = await originalRecovery.exportLostOutputProof({...options,output:absolute(input.destination)});
              native = {...await queue.show(intentId), lostOutputProof:exported};
            }
          } else if (input.command === 'show') native = await queue.show(intentId);
          else if (input.command === 'response') {
            native = await queue.show(intentId);
            const file = join(root, 'jobs', native.id, 'execution.json');
            need(digest(await readBytes(file)) === native.configSha256, 'INBOX_CONFIG_CHANGED');
            const config = await original('config.mjs');
            responseFile = config.responseFile(await config.config(file));
          } else if (input.command === 'recover') native = await queue.recover(intentId);
          else if (input.command === 'cancel') native = await queue.cancel(intentId);
          else if (input.command === 'execute') {
            const job = await queue.show(intentId), review = input.review;
            need(object(review) && review.root === root && review.intentId === intentId &&
              review.configSha256 === job.configSha256 && review.bodySha256 === job.bodySha256 &&
              review.ticketSha256 === (job.operationTicket?.sha256 ?? null), 'MATCHING_INBOX_REVIEW_REQUIRED');
            native = await queue.run(intentId, { signal:controller.signal,
              ...(input.workspaceDirectory === undefined ? {} : {workspace:input.workspaceDirectory}) });
          } else if (input.command === 'finalize') {
            const { finalizeQueueIntent } = await original('finalization.mjs');
            native = await finalizeQueueIntent({ root, intentId, workspace:input.workspaceDirectory,
              outbox:input.outboxDirectory, merchantRoute:input.merchantRoute, signal:controller.signal });
            if (!['FINALIZED','IDEMPOTENT_FINALIZED'].includes(native.finalization?.result?.outcome) ||
              native.finalizationView?.status !== 'SAVED') process.exitCode = 2;
          } else need(false, 'INBOX_COMMAND_REQUIRED');
          if (input.command === 'execute' && native.lastError) process.exitCode = 2;
        }
      }
    }
  } catch (problem) {
    error = safeCode(problem?.code, 'INBOX_OPERATION_FAILED');
    // The native attempt may already exist. Return its original current view
    // when readable; never clear a marker or dispatch another intent.
    if (queue && input.intentId) {
      try { native = await queue.show(input.intentId); } catch { /* Keep the original error. */ }
    }
    process.exitCode = signalExit ?? 1;
  }
  await writeJson(absolute(resultFile), { schema:SCHEMA, command:input.command,
    root:input.root ?? null, native, responseFile, error }, { exclusive:true });
  if (signalExit !== undefined) process.exitCode = signalExit;
}

main(process.argv.slice(2)).catch(error => {
  process.stderr.write(JSON.stringify({ error:safeCode(error?.code, 'INBOX_WORKER_FAILED'),
    retry:'NO_AUTOMATIC_RETRY' }) + '\n');
  process.exitCode = signalExit ?? 1;
}).finally(() => { process.removeListener('SIGINT', interrupt); process.removeListener('SIGTERM', terminate); });

// MIT — Node customer workflow on the original durable, exact-intent inbox.
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { BuyerResult, VerifiedFile } from './result.mjs';
import { absolute, intent, digest, object, need, BuyerError, safeCode, now,
  readJson, writeJson, syncDirectory } from './store.mjs';

const SCHEMA = 'stellar-forge.node-buyer-inbox-command.v1';
const INBOX = 'stellar-forge.sf88.buyer-inbox.v1';
const worker = fileURLToPath(new URL('./inbox-worker.mjs', import.meta.url));
const freeze = value => {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
};

export class InboxResult {
  constructor(run, commandDirectory) {
    this.native = freeze(structuredClone(run.output?.native ?? null));
    this.process = Object.freeze({ exitCode:run.exitCode ?? null,
      exitSignal:run.exitSignal ?? null, errorCode:run.errorCode ?? run.output?.error ?? null });
    this.commandDirectory = commandDirectory;
    Object.freeze(this);
  }
}

export class InboxError extends BuyerError {
  constructor(code, result, details = {}) {
    super(code, { result, ...details });
    this.name = 'InboxError';
  }
}

async function command(buyer, commandName, input, {signal} = {}) {
  need(signal === undefined || signal instanceof AbortSignal, 'INVALID_ABORT_SIGNAL');
  need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
  await buyer.ready();
  const directory = await mkdtemp(join(buyer.stateDirectory, '.inbox-command-'));
  const inputFile = join(directory, 'request.json'), resultFile = join(directory, 'native.json');
  let run;
  try {
    await writeJson(inputFile, { schema:SCHEMA, command:commandName, ...input }, { exclusive:true });
    await syncDirectory(buyer.stateDirectory);
    run = await buyer.runtime.run([buyer.runtime.directory, inputFile, resultFile], {
      directory, signal, entryFile:worker, resultFile, resultLimit:buyer.inboxReportLimit,
    });
    const output = run.output;
    need(object(output) && output.schema === SCHEMA && output.command === commandName &&
      output.root === (input.root ?? null), 'INBOX_NATIVE_RESULT_UNAVAILABLE');
    if (output.error) throw new BuyerError(output.error);
    need(object(output.native), 'INBOX_NATIVE_RESULT_INVALID');
    if (input.intentId) need(output.native.schema === INBOX &&
      output.native.operation?.intentId === input.intentId, 'INBOX_NATIVE_INTENT_MISMATCH');
    if (run.errorCode || run.exitSignal || ![0,2].includes(run.exitCode))
      throw new BuyerError(run.errorCode ?? 'INBOX_NATIVE_COMMAND_FAILED');
    let retained = null;
    try { await rm(directory, { recursive:true, force:true }); }
    catch { retained = directory; }
    // Cleanup cannot turn a known native completion into an uncertain action.
    const result = new InboxResult(run, retained);
    return { result, responseFile:output.responseFile };
  } catch (problem) {
    const result = new InboxResult(run ?? { errorCode:safeCode(problem?.code, 'INBOX_NATIVE_COMMAND_FAILED') }, directory);
    throw new InboxError(safeCode(problem?.code, 'INBOX_NATIVE_COMMAND_FAILED'), result,
      { commandDirectory:directory, ...(input.intentId ? {intentId:input.intentId} : {}),
        ...(input.root ? {inboxDirectory:input.root} : {}) });
  }
}

function lostOutputSelection({approvedRequestFile,approvedRequest,expectedRequestSha256,expectedAttemptId,expectedConfigSha256}) {
  need((approvedRequestFile !== undefined) !== (approvedRequest !== undefined),
    'LOST_OUTPUT_ONE_APPROVED_REQUEST_SOURCE_REQUIRED');
  if (approvedRequest !== undefined) need(object(approvedRequest), 'LOST_OUTPUT_APPROVED_REQUEST_REQUIRED');
  const input = approvedRequestFile === undefined
    ? {approvedRequest:structuredClone(approvedRequest)} : {approvedRequestFile:absolute(approvedRequestFile)};
  for (const [name,value] of Object.entries({expectedRequestSha256,expectedAttemptId,expectedConfigSha256})) {
    if (value === undefined) continue;
    need(typeof value === 'string' && (name === 'expectedAttemptId'
      ? /^[A-Za-z0-9._:-]{1,128}$/.test(value) : /^[a-f0-9]{64}$/.test(value)),
      'LOST_OUTPUT_SELECTED_ATTEMPT_INVALID');
    input[name] = value;
  }
  return input;
}

/** Inspect the complete private merchant packet with the installed native reader. */
export async function inspectOperationHandoff(buyer, file, {accept, signal} = {}) {
  if (accept !== undefined) need(Number.isSafeInteger(accept) && accept >= 0, 'EXPLICIT_SELECTION_INDEX_REQUIRED');
  const {result} = await command(buyer, 'inspect-packet', {file:absolute(file),
    ...(accept === undefined ? {} : {accept})}, {signal});
  need(Array.isArray(result.native.choices) && typeof result.native.intentId === 'string', 'INBOX_PACKET_VIEW_INVALID');
  return result.native;
}

export async function createInbox(buyer, {directory, signal}) {
  const inbox = new Inbox(buyer, directory);
  await inbox._command('create', {}, {signal});
  return inbox;
}

export class Inbox {
  constructor(buyer, directory) {
    this.buyer = buyer;
    this.directory = absolute(directory);
  }
  _command(name, input = {}, options = {}) {
    return command(this.buyer, name, { root:this.directory, ...input }, options).then(value => value.result);
  }
  list(options) { return this._command('list', {}, options); }
  show(intentId, options) { return this._command('show', {intentId:intent(intentId)}, options); }

  async enqueue(operation, options) {
    need(operation?.buyer === this.buyer && typeof operation._bound === 'function', 'SAME_BUYER_OPERATION_REQUIRED');
    await this._command('open', {}, options);
    const {meta} = await operation._bound();
    const binding = {schema:'stellar-forge.node-buyer.v1', intentId:operation.intentId,
      state:'INBOX_DELEGATED', kind:'INBOX_DELEGATED', inboxDirectory:this.directory,
      configSha256:meta.configSha256, bodySha256:meta.bodySha256,
      ticketSha256:meta.ticketSha256 ?? null, createdAt:now(), retry:'NO_AUTOMATIC_RETRY'};
    const attemptFile = join(operation.directory, 'attempt.json');
    try { await writeJson(attemptFile, binding, {exclusive:true}); }
    catch (error) {
      if (error.code !== 'EEXIST') throw error;
      const saved = await readJson(attemptFile);
      need(['schema','intentId','kind','inboxDirectory','configSha256','bodySha256','ticketSha256']
        .every(key => saved[key] === binding[key]), 'OPERATION_ALREADY_ASSIGNED_OR_ATTEMPTED');
    }
    // This immutable routing marker precedes native intake. Repeating only the
    // SAME intake is safe after a crash; native enqueue owns identical-intent checks.
    return this._command('enqueue', { configFile:operation.configPath,
      expectedConfigSha256:meta.configSha256, expectedBodySha256:meta.bodySha256,
      expectedTicketSha256:meta.ticketSha256 ?? null }, options);
  }

  enqueueConfig(configFile, options) {
    return this._command('enqueue', {configFile:absolute(configFile)}, options);
  }

  async review(intentId, {signal} = {}) {
    intentId = intent(intentId);
    const before = (await this.show(intentId, {signal})).native;
    const native = await this.buyer.runtime.checked(['--review', '--config',
      join(this.directory, 'jobs', before.id, 'execution.json')], {
      stateDirectory:this.buyer.stateDirectory, mode:'OFFLINE_REVIEW', signal,
    });
    const after = (await this.show(intentId, {signal})).native;
    need(before.configSha256 === after.configSha256 && before.bodySha256 === after.bodySha256 &&
      (before.operationTicket?.sha256 ?? null) === (after.operationTicket?.sha256 ?? null) &&
      native.intentId === intentId && native.bodySha256 === (after.bodySha256 ?? digest(Buffer.alloc(0))) &&
      (native.operationTicket?.sha256 ?? null) === (after.operationTicket?.sha256 ?? null), 'INBOX_REVIEW_BINDING_MISMATCH');
    return freeze({root:this.directory, intentId, configSha256:after.configSha256,
      bodySha256:after.bodySha256, ticketSha256:after.operationTicket?.sha256 ?? null,
      reviewedAt:now(), native});
  }

  execute(intentId, {review, workspaceDirectory, signal} = {}) {
    intentId = intent(intentId);
    need(review?.root === this.directory && review.intentId === intentId, 'MATCHING_INBOX_REVIEW_REQUIRED');
    const pins = Object.fromEntries(['root','intentId','configSha256','bodySha256','ticketSha256']
      .map(key => [key, review[key]]));
    return this._command('execute', {intentId, review:pins,
      ...(workspaceDirectory === undefined ? {} : {workspaceDirectory:absolute(workspaceDirectory)})}, {signal});
  }
  inspectLostOutput(intentId, {workspaceDirectory, approvedRequestFile, approvedRequest,
    expectedRequestSha256, expectedAttemptId, expectedConfigSha256, signal} = {}) {
    return this._command('inspect-lost-output', {intentId:intent(intentId),
      workspaceDirectory:absolute(workspaceDirectory),
      ...lostOutputSelection({approvedRequestFile,approvedRequest,expectedRequestSha256,expectedAttemptId,expectedConfigSha256})}, {signal});
  }
  recoverLostOutput(intentId, {workspaceDirectory, transaction, approvedRequestFile, approvedRequest,
    expectedRequestSha256, expectedAttemptId, expectedConfigSha256, signal} = {}) {
    need(typeof transaction === 'string' && /^[a-f0-9]{64}$/.test(transaction) &&
      typeof expectedRequestSha256 === 'string' && /^[a-f0-9]{64}$/.test(expectedRequestSha256),
      'LOST_OUTPUT_TRANSACTION_AND_DIGEST_REQUIRED');
    return this._command('recover-lost-output', {intentId:intent(intentId),
      workspaceDirectory:absolute(workspaceDirectory), transaction,
      ...lostOutputSelection({approvedRequestFile,approvedRequest,expectedRequestSha256,expectedAttemptId,expectedConfigSha256})}, {signal});
  }
  readLostOutputRecovery(intentId, {workspaceDirectory, signal} = {}) {
    return this._command('read-lost-output', {intentId:intent(intentId),
      workspaceDirectory:absolute(workspaceDirectory)}, {signal});
  }
  exportLostOutputProof(intentId, destination, {workspaceDirectory, signal} = {}) {
    return this._command('export-lost-output', {intentId:intent(intentId),
      workspaceDirectory:absolute(workspaceDirectory), destination:absolute(destination)}, {signal});
  }
  cancel(intentId, options) { return this._command('cancel', {intentId:intent(intentId)}, options); }
  recover(intentId, options) { return this._command('recover', {intentId:intent(intentId)}, options); }
  finalize(intentId, {workspaceDirectory, outboxDirectory, merchantRoute, signal} = {}) {
    return this._command('finalize', {intentId:intent(intentId), workspaceDirectory:absolute(workspaceDirectory),
      ...(outboxDirectory === undefined ? {} : {outboxDirectory:absolute(outboxDirectory)}),
      ...(merchantRoute === undefined ? {} : {merchantRoute})}, {signal});
  }
  exportReport(destination, {workspaceDirectory, signal} = {}) {
    return this._command('report', {destination:absolute(destination),
      ...(workspaceDirectory === undefined ? {} : {workspaceDirectory:absolute(workspaceDirectory)})}, {signal});
  }
  async response(intentId, {signal} = {}) {
    const {result, responseFile} = await command(this.buyer, 'response', {
      root:this.directory, intentId:intent(intentId)}, {signal});
    const job = result.native;
    if (!job.outcome || !responseFile) return null;
    need(job.outcome.mode === 'ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT' &&
      job.outcome.intentId === intentId && responseFile.destination === job.responseDestination,
    'INBOX_RESPONSE_BINDING_MISMATCH');
    return new InboxResponse(job, responseFile, this.buyer.runtime.directory);
  }
}

/** Saved native response bytes. A current inbox read is not an old process exit. */
export class InboxResponse extends VerifiedFile {
  constructor(job, responseFile, runtimeDirectory) {
    super();
    this.job = freeze(structuredClone(job));
    this.responseFile = freeze(structuredClone(responseFile));
    this.runtimeDirectory = absolute(runtimeDirectory);
  }
  get native() { return this.job.outcome; }
  get status() { return this.native.status; }
  get delivery() { return this.native.responseFile ?? {status:'NOT_REQUESTED'}; }
  get stream() { return this.delivery.stream ?? null; }
  // Reuse the shipped response pin checks and original SF31 stream codec without
  // constructing an invented BuyerResult record or duplicating its parser.
  _metadata() { return BuyerResult.prototype._metadata.call(this); }
  _records(format, options) { return BuyerResult.prototype._records.call(this, format, options); }
  events(options) { return BuyerResult.prototype.events.call(this, options); }
  ndjson(options) { return BuyerResult.prototype.ndjson.call(this, options); }
}

export type JsonObject = { [key: string]: unknown };
export interface OperatorProfile {
  operator?: { python: string; actor: string; service: string; policy: string; ledger: string };
  signerModule?: string;
  trustedPayer?: string;
  bodyCaptureTimeoutMs?: number;
  /** Per native HTTP exchange, including response body; 1–300,000 ms. */
  requestTimeoutMs?: number;
