    updateBusy(){renderScope();renderCurrent();}
  };
}

*{box-sizing:border-box}
:root{font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#202326;background:#f6f7f8;font-size:14px;line-height:1.5;--line:#d9dde1;--muted:#616870;--surface:#fff;--soft:#f2f4f5;--dark:#252b31}
body{margin:0}
button,input,select,textarea{font:inherit;color:inherit}
button{min-height:36px;padding:7px 13px;border:1px solid #bdc3c9;border-radius:4px;background:#fff;cursor:pointer;font-weight:550;white-space:nowrap}
button:hover{background:#edf0f2;border-color:#929ba4}
button:disabled{opacity:.48;cursor:default}
button.primary{background:var(--dark);border-color:var(--dark);color:#fff}
button.primary:hover{background:#11171d}
button.quiet{background:transparent;border-color:transparent}
button.quiet:hover{background:#e8ecef}
button.compact{min-height:30px;padding:4px 9px;font-size:12px}
input,select,textarea{width:100%;padding:9px 10px;border:1px solid #c8cdd2;background:#fff;border-radius:4px}
input:focus,select:focus,textarea:focus,button:focus-visible,a:focus-visible{outline:2px solid #4c555f;outline-offset:2px}
textarea{resize:vertical}
input[type=checkbox]{width:16px;height:16px;padding:0;margin:0;accent-color:#343a41;flex:0 0 auto}
input[type=search]::-webkit-search-cancel-button{cursor:pointer}
a{color:#293e54;text-decoration:underline;text-underline-offset:2px}
a:hover{color:#111}
h1,h2,h3,p{margin:0}
h1{font-size:25px;line-height:1.25;font-weight:630;letter-spacing:-.4px}
h2{font-size:17px;font-weight:620;line-height:1.4}
h3{font-size:13px;font-weight:650;line-height:1.4}
p{margin-top:8px}
[hidden]{display:none!important}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.skip-link{position:fixed;top:-80px;left:15px;z-index:30;background:#fff;padding:10px;border:1px solid #333}
.skip-link:focus{top:10px}
.muted{color:var(--muted)}
.small{font-size:12px}
.eyebrow{font-size:10px;letter-spacing:1.1px;text-transform:uppercase;color:var(--muted);font-weight:650}
.topbar{height:60px;background:#fff;border-bottom:1px solid var(--line);padding:0 24px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.brand{display:flex;align-items:center;gap:10px;font-size:15px;font-weight:650;letter-spacing:-.2px}
.brand-mark{display:grid;place-items:center;border:1px solid #939aa2;width:27px;height:27px;font:700 15px ui-monospace,SFMono-Regular,monospace}
.topbar-right{display:flex;align-items:center;gap:20px}
#connection{color:var(--muted);font-size:12px}
.notice{padding:10px 24px;border-bottom:1px solid #b8bec4;background:#eceff1;font-size:13px;overflow-wrap:anywhere}
.notice[data-kind=error]{border-left:4px solid #565c62}
.shell{display:grid;grid-template-columns:232px minmax(0,1fr);min-height:calc(100vh - 60px)}
.collection{background:#f1f3f5;border-right:1px solid var(--line);padding:20px 14px;display:flex;flex-direction:column;min-height:calc(100vh - 60px)}
.section-heading{display:flex;align-items:center;justify-content:space-between;margin:0 4px 14px}
.section-heading h2{font-size:12px;text-transform:uppercase;letter-spacing:.75px;color:#545b63}
.search-field{display:block;margin:0}
.collection .search-field input{font-size:12px;padding:8px}
.dossier-list{margin:14px -4px;display:flex;flex-direction:column;gap:4px}
.dossier-item{display:flex;flex-direction:column;width:100%;align-items:flex-start;text-align:left;border-color:transparent;white-space:normal;padding:11px 10px;background:transparent;gap:5px}
.dossier-item strong{font-size:13px;line-height:1.4;font-weight:600;overflow-wrap:anywhere}
.dossier-item span{font-size:11px;color:var(--muted);font-weight:400}
.dossier-item.active{background:#fff;border-color:#c9cfd5;box-shadow:0 1px 1px #00000005}
.collection-footer{margin-top:auto;padding:24px 4px 0;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px;color:var(--muted);font-size:11px}
main{min-width:0;padding:30px 32px 48px;max-width:1900px}
.empty-workspace{max-width:820px;margin:50px auto;padding:30px}
.empty-workspace h1{font-size:32px;max-width:600px;margin-top:12px}
.empty-workspace>p{max-width:620px;font-size:15px;color:var(--muted);line-height:1.7}
.button-row{display:flex;gap:10px;margin-top:24px}
.getting-started{margin:44px 0 0;padding:0;list-style-position:inside;display:grid;grid-template-columns:1fr 1fr;gap:24px 32px;border-top:1px solid var(--line);padding-top:26px}
.getting-started li{font-size:13px}
.getting-started strong{font-weight:620}
.getting-started span{display:block;margin-top:5px;color:var(--muted)}
.dossier-header{display:flex;justify-content:space-between;gap:30px;align-items:flex-start}
.title-block{min-width:0}
.title-block h1{margin-top:6px;overflow-wrap:anywhere}
.title-block>p{max-width:820px;white-space:pre-wrap;overflow-wrap:anywhere}
.header-actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}
.record-meta{display:flex;flex-wrap:wrap;gap:5px 16px;font-size:11px;color:var(--muted);margin-top:12px}
.summary-strip{display:flex;gap:34px;margin-top:26px;padding:16px 0 20px;border-bottom:1px solid var(--line)}
.summary-strip>div{display:flex;align-items:baseline;gap:8px}
.summary-strip span{font:500 21px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:-.5px}
.summary-strip label{color:var(--muted);font-size:11px}
.tabs{display:flex;gap:22px;margin:0 0 22px;border-bottom:1px solid var(--line)}
.tab{border:0;border-radius:0;background:transparent;padding:14px 2px 12px;color:var(--muted);font-size:13px;border-bottom:2px solid transparent}
.tab:hover{background:transparent;color:#222}
.tab.active{color:#1d2329;border-bottom-color:#252b31}
.source-toolbar{display:flex;gap:10px;align-items:center;margin-bottom:12px;flex-wrap:wrap}
.grow{flex:1 1 250px}
.source-toolbar input,.source-toolbar select{font-size:12px}
.field-inline{width:210px}
.check-filter{display:flex;align-items:center;gap:8px;font-size:12px;white-space:nowrap;padding:6px}
.source-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:20px;align-items:start}
.source-layout.has-detail{grid-template-columns:minmax(350px,1fr) minmax(280px,350px)}
.sources-area{min-width:0}
.table-caption{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:8px 0;color:var(--muted);font-size:11px}
.sort-label{display:flex;gap:6px;align-items:center;white-space:nowrap}
.sort-label select{font-size:11px;width:auto;border:0;background:transparent;padding:4px}
.table-wrap{border:1px solid var(--line);border-radius:4px;background:#fff;overflow:auto}
table{border-collapse:collapse;width:100%}
th{font-size:10px;text-transform:uppercase;letter-spacing:.55px;color:#636a72;text-align:left;padding:10px 12px;background:#f5f6f7;border-bottom:1px solid var(--line);font-weight:650}
td{padding:14px 12px;vertical-align:top;border-bottom:1px solid #e4e7e9}
tbody tr:last-child td{border-bottom:0}
tbody tr:hover{background:#fafbfc}
tbody tr.focused{background:#f0f3f5}
.select-column{width:42px;padding-left:14px;padding-right:8px}
td.select-column{padding-top:18px}
.coverage-column{width:105px}
.date-column{width:105px}
.source-title{border:0;background:transparent;padding:0;text-align:left;white-space:normal;min-height:0;font-size:13px;font-weight:600;line-height:1.5;color:#20262c;display:block}
.source-title:hover{background:none;text-decoration:underline}
.source-host{font-size:10px;color:#68717a;margin-top:5px;overflow-wrap:anywhere}
.source-snippet{font-size:12px;color:#5e666e;line-height:1.6;margin-top:7px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
.source-tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}
.tag{display:inline-block;font-size:10px;background:#f0f2f4;border:1px solid #dce0e4;color:#535d66;border-radius:3px;padding:1px 6px}
.cell-detail{font-size:11px;line-height:1.6;color:#5d6670}
.pagination{display:flex;justify-content:flex-end;align-items:center;gap:14px;margin-top:10px;font-size:11px;color:var(--muted)}
