.source-detail section h3{margin-bottom:10px}
.evidence-toggle{display:flex;align-items:center;gap:8px;font-size:12px;padding:10px;margin-top:18px;background:#f2f4f5;border:1px solid #dde1e5;border-radius:4px}
.source-excerpt{font-size:12px;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto}
.citation-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px;font-size:11px;color:#606971}
