.view-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin:26px 0 18px}
.view-heading p{font-size:12px}
.question-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(320px,100%),1fr));gap:12px}
.question-card{background:#fff;border:1px solid var(--line);border-radius:4px;padding:18px}
