.edition-item strong{font-size:12px;font-weight:580}
.edition-item p{font-size:11px;color:var(--muted);margin-top:4px}
.edition-item>span{font-size:11px;color:var(--muted);white-space:nowrap}
.compare-controls{display:flex;gap:16px;align-items:flex-end;flex-wrap:wrap;background:#fff;padding:18px;border:1px solid var(--line);border-radius:4px}
.compare-controls label{font-size:12px;font-weight:550;min-width:200px;flex:1}
.compare-controls select{display:block;margin-top:6px;font-size:12px}
.comparison{margin-top:18px}
.comparison-summary{display:flex;gap:20px;padding:16px 18px;border:1px solid var(--line);background:#fff;border-radius:4px;flex-wrap:wrap}
