.change-list li:last-child{border-bottom:0}
.change-list span{display:block;color:var(--muted);font-size:11px;margin-top:3px}
.history-heading{margin-top:32px}
.revision-list{list-style:none;padding:0;margin:14px 0 0}
.revision-list li{display:grid;grid-template-columns:95px minmax(0,1fr) auto;gap:14px;align-items:baseline;padding:13px 4px;border-bottom:1px solid var(--line);font-size:12px}
.revision-list time{font-size:11px;color:var(--muted)}
.revision-number{font:11px ui-monospace,SFMono-Regular,monospace;color:#515b64}
dialog{border:1px solid #bac2c9;border-radius:6px;padding:25px;background:#fff;max-width:calc(100vw - 32px);width:480px;box-shadow:0 15px 60px #00000021;color:inherit}
dialog::backdrop{background:#242b3366}
