dialog form>label{display:block;margin:16px 0 0;font-size:12px;font-weight:550}
dialog label input,dialog label textarea,dialog label select{display:block;margin-top:7px;font-weight:400;font-size:13px}
dialog p{font-size:13px}
.dialog-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:24px;padding-top:17px;border-top:1px solid #e0e4e7}
.form-error{background:#f0f2f4;border-left:3px solid #616a73;padding:10px 12px;font-size:12px;overflow-wrap:anywhere;margin-top:18px}
.file-picker{padding:16px;border:1px dashed #b9c1c8;background:#f7f8f9;border-radius:4px}
.file-picker input{border:0;background:transparent;padding:8px 0}
.file-picker span{display:block;margin-top:8px;font-weight:400}
.selected-files{font-size:11px;color:var(--muted);margin-top:12px}
.selected-files div{display:flex;justify-content:space-between;gap:10px;padding:5px 0;border-bottom:1px solid #eceff1;overflow-wrap:anywhere}
body.working{cursor:progress}
@media(min-width:1500px){main{padding-left:42px;padding-right:42px}.source-layout.has-detail{grid-template-columns:minmax(420px,1fr) 390px}}
@media(max-width:1150px){.shell{grid-template-columns:195px minmax(0,1fr)}main{padding:24px}.dossier-header{flex-direction:column;gap:18px}.header-actions{justify-content:flex-start}.summary-strip{gap:23px}.summary-strip>div{flex-direction:column;gap:1px}.source-layout.has-detail{grid-template-columns:1fr}.source-detail{position:relative;top:0;max-height:none;grid-row:1}.field-inline{width:190px}}
@media(max-width:760px){.topbar{height:auto;min-height:58px;padding:12px 16px;flex-wrap:wrap;gap:9px}.topbar-right{gap:10px}.topbar-right button{font-size:11px;min-height:28px;padding:4px 6px}#connection{font-size:10px}.shell{display:block}.collection{min-height:0;border-right:0;border-bottom:1px solid var(--line);padding:14px 16px}.collection .section-heading{margin:0 0 10px}.collection .search-field{display:none}.dossier-list{flex-direction:row;overflow:auto;margin:0;gap:7px;padding-bottom:2px}.dossier-item{min-width:170px;max-width:240px;padding:8px 10px}.dossier-item span{font-size:10px}.collection-footer{display:none}main{padding:22px 16px 36px}.empty-workspace{margin:10px auto;padding:10px 0}.empty-workspace h1{font-size:27px}.getting-started{gap:22px;margin-top:32px}.summary-strip{justify-content:space-between;gap:12px;margin-top:20px;padding-bottom:16px}.summary-strip label{font-size:9px}.summary-strip span{font-size:18px}h1{font-size:22px}.header-actions{gap:5px}.header-actions button{font-size:12px;padding:6px 10px}.tabs{margin-bottom:16px}.source-toolbar .grow{flex-basis:100%}.field-inline{flex:1}.check-filter{font-size:11px}.coverage-column{width:77px}.date-column{display:none}.date-cell{display:none}th,td{padding:10px}.select-column{width:30px;padding-left:10px;padding-right:4px}.source-title{font-size:12px}.source-snippet{font-size:11px;-webkit-line-clamp:2}.source-host{font-size:9px}.source-detail{padding:15px}.view-heading{margin-top:20px}.view-heading h2{font-size:16px}.view-heading button{font-size:12px}.edition-item{flex-direction:column;gap:5px}.compare-controls{padding:14px}.compare-controls label{min-width:150px}.revision-list li{grid-template-columns:75px 1fr;gap:6px 10px}.revision-list time{grid-column:2}.notice{padding:10px 16px}.getting-started li{font-size:12px}}
@media(prefers-reduced-motion:no-preference){button{transition:background-color .12s,border-color .12s}}

.stack-label{display:block;font-size:12px;font-weight:550;margin-top:16px}
.stack-label>input,.stack-label>textarea,.stack-label>select{margin-top:7px;font-weight:400}
.import-modes{display:flex;gap:16px;padding:12px;background:#f2f4f5;border:1px solid var(--line);border-radius:4px}
.import-modes label{display:flex;gap:7px;align-items:center;font-size:12px}
.import-modes input{width:15px;height:15px;margin:0;accent-color:#353b42}
#detail-classification{font-size:12px}
.finding-list{display:flex;flex-direction:column;gap:14px}
.finding-card{padding:20px;background:#fff;border:1px solid var(--line);border-radius:4px}
.finding-card h3{font-size:15px;font-weight:600}
.finding-card .finding-text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.8;margin-top:12px}
.finding-card .finding-source-list{margin-top:16px;padding-top:12px;border-top:1px solid #e4e7e9;display:flex;flex-wrap:wrap;gap:6px}
.finding-source-list button{font-size:11px;font-weight:450;text-align:left;white-space:normal}
.source-picks{border:1px solid var(--line);border-radius:4px;margin:20px 0 0;padding:12px 14px}
.source-picks legend{font-size:12px;font-weight:600;padding:0 5px}
#finding-sources{max-height:240px;overflow:auto;display:flex;flex-direction:column;gap:11px}
.source-pick{display:flex;gap:9px;align-items:flex-start;font-size:12px}
.source-pick input{margin-top:2px}
.source-pick span{display:block;color:var(--muted);font-size:10px;margin-top:3px}
.provider-outcome{padding:9px 12px;background:#f0f2f4;border:1px solid #d9dee3;border-radius:4px;margin-top:8px;font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}
.typed-content{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px}
.availability{font-size:10px;color:#4c5660;border:1px solid #c9d0d7;display:inline-block;padding:2px 6px;margin-top:9px;border-radius:3px;background:#f0f3f5}
.question-note{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;color:var(--muted);line-height:1.7;margin-top:10px}

.unavailable-sources{border:1px solid var(--line);background:#fff;padding:16px;border-radius:4px;margin-top:18px}
.unavailable-source-item{border-top:1px solid #e2e6e9;margin-top:12px;padding-top:12px;font-size:12px}
.unavailable-source-item .reference-code{font-family:ui-monospace,SFMono-Regular,monospace;font-size:10px;overflow-wrap:anywhere;color:var(--muted)}
.unavailable-source-item p{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.75}

dialog form>label.replace-sources,dialog form>label.saved-selection-check{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:500}
dialog .replace-sources input,dialog .saved-selection-check input{display:inline-block;width:16px;height:16px;margin:0}
.finding-card-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:15px}
.finding-card-heading>div{min-width:0}
