.excerpt-heading{margin-bottom:10px}
.excerpt-heading select{font-size:11px;margin-top:7px}
.finding-availability{font-size:11px;color:var(--muted);margin-top:10px}

/* Original occurrences and authored finding revisions. */
.original-record{margin-top:.65rem;font-size:.78rem}
.original-record summary{cursor:pointer;font-weight:600;color:#484c50}
.original-record pre{max-height:22rem;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f4f4;border:1px solid #d8dadd;padding:.75rem;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.74rem;line-height:1.55}
.finding-change{padding:1rem 0;border-top:1px solid #dedfe1}
.finding-change h4{margin:0 0 .35rem;font-size:.92rem}
.finding-change-versions{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,18rem),1fr));gap:1rem;margin-top:.75rem}
.finding-change-versions>section{min-width:0;background:#f8f8f8;border:1px solid #e0e1e2;padding:.85rem}
.finding-change-versions>section>strong{font-size:.73rem;text-transform:uppercase;letter-spacing:.045em}
.finding-change-versions>section>p{font-weight:600;font-size:.84rem}
.finding-change-versions>section>pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;font-size:.83rem;line-height:1.6}

/* DOI acquisition shares the original industrial research workspace. */
.crossref-form{border:1px solid var(--line);background:#fff;border-radius:4px;padding:18px;display:grid;grid-template-columns:minmax(0,2fr) minmax(180px,1fr);gap:16px}
.crossref-form>label{font-size:12px;font-weight:550}
.crossref-form>label>input,.crossref-form>label>select{margin-top:6px;font-weight:400}
.crossref-options,.crossref-form>p,.crossref-form-footer{grid-column:1/-1}
.crossref-options{display:flex;flex-wrap:wrap;gap:14px 22px}
.crossref-options label{display:flex;align-items:center;gap:8px;font-size:12px}
.crossref-form-footer{display:flex;gap:16px;justify-content:space-between;align-items:center}
.crossref-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:20px;margin-top:24px;align-items:start}
.crossref-history{min-width:0}
.crossref-history h3{margin-bottom:12px}
.crossref-operation{display:flex;flex-direction:column;width:100%;align-items:flex-start;text-align:left;white-space:normal;background:#fff;margin-bottom:8px;padding:12px;gap:5px}
.crossref-operation strong{font-size:12px;font-weight:600;overflow-wrap:anywhere}
.crossref-operation span{font-size:10px;color:var(--muted);font-weight:400}
.crossref-operation.active{border-color:#626a72;background:#eef0f2}
.crossref-review{min-width:0;padding:20px;border:1px solid var(--line);background:#fff;border-radius:4px}
.crossref-review-heading{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}
.crossref-review-heading h3{font-size:16px}
.crossref-review-heading p{font-size:12px;color:var(--muted)}
.crossref-actions{flex-wrap:wrap;margin-top:18px}
#crossref-plan-question{font-size:13px;line-height:1.7;overflow-wrap:anywhere}
#crossref-result{margin-top:28px;border-top:1px solid var(--line);padding-top:20px}
#crossref-result>.table-wrap{margin-top:14px}
#crossref-result td{font-size:11px}
#crossref-result .source-title{font-size:12px}
.crossref-record-detail{margin-top:18px;padding:16px;background:#f5f6f7;border:1px solid var(--line);border-radius:4px;overflow-wrap:anywhere}
.crossref-record-detail>h3{margin-top:16px}
.crossref-record-detail>h3:first-child{margin-top:0}
.crossref-record-detail>table{margin:14px 0;font-size:11px}
.crossref-record-detail>table th{width:150px;text-transform:none}
.crossref-record-detail>a{font-size:11px}
.tabs{overflow-x:auto;flex-wrap:nowrap}
@media(max-width:1150px){.crossref-layout{grid-template-columns:180px minmax(0,1fr)}}
@media(max-width:760px){.crossref-form{grid-template-columns:1fr;padding:14px}.crossref-form-footer{align-items:flex-start;flex-direction:column}.crossref-layout{grid-template-columns:1fr;gap:16px}.crossref-history>div{display:flex;gap:8px;overflow:auto}.crossref-operation{min-width:190px;max-width:240px}.crossref-review{padding:14px}.crossref-review-heading{flex-direction:column;gap:8px}.crossref-options{gap:12px}.crossref-record-detail{padding:12px}}

/* Original research document review: neutral industrial surfaces. */
.document-layout{display:grid;grid-template-columns:minmax(200px,260px) minmax(0,1fr);gap:24px;align-items:start}
.document-history{border-right:1px solid #c7c7c7;padding-right:20px;min-width:0}
.document-history h3{font-size:14px;margin:18px 0 8px}
.document-item{display:flex;flex-direction:column;gap:5px;width:100%;text-align:left;overflow-wrap:anywhere;background:#fff;border:1px solid #c7c7c7;padding:10px;margin:0 0 8px;border-radius:2px}
.document-item.active{border-color:#292929;box-shadow:inset 3px 0 0 #292929}
.document-review{min-width:0}.document-review h3{overflow-wrap:anywhere}
.document-status{display:flex;gap:24px;border-top:1px solid #c7c7c7;border-bottom:1px solid #c7c7c7;margin:12px 0}
.document-status p{display:flex;flex-direction:column;gap:5px;font-size:13px;overflow-wrap:anywhere}
.document-receive-form{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;margin:20px 0;padding:16px;background:#f4f4f4;border:1px solid #c7c7c7}
.document-receive-form .button-row,.document-receive-form p{grid-column:1/-1}
.document-filter{display:grid;grid-template-columns:minmax(100px,1fr) minmax(120px,1fr) minmax(140px,2fr) auto;align-items:end;gap:10px;margin:18px 0}
.document-filter label,.document-receive-form label{display:flex;flex-direction:column;gap:6px;font-size:13px;min-width:0}
.document-filter input,.document-filter select,.document-receive-form input,.document-receive-form select{width:100%;min-width:0}
.document-elements{display:flex;flex-direction:column;gap:8px}
.document-element{display:flex;flex-direction:column;gap:6px;width:100%;text-align:left;border:1px solid #c7c7c7;background:#fff;padding:12px;border-radius:2px;white-space:pre-wrap;overflow-wrap:anywhere}
.document-element:hover,.document-item:hover{background:#f4f4f4}
.document-element-detail{margin-top:20px;padding-top:16px;border-top:1px solid #c7c7c7;min-width:0}
.document-full-text,.document-review pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:normal;max-width:100%}
.document-full-text{font:inherit;font-size:14px;line-height:1.55;border:1px solid #c7c7c7;padding:14px;background:#f7f7f7}
@media(max-width:900px){.document-layout{grid-template-columns:1fr}.document-history{border-right:0;border-bottom:1px solid #c7c7c7;padding:0 0 16px}.document-filter{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.document-filter,.document-receive-form{grid-template-columns:1fr}.document-status{flex-direction:column;gap:0}.document-status p{margin:8px 0}.document-layout{gap:14px}}
